"""Original liver tests and jaundice chapter."""
from qbank_authoring import question,ref,finalize
ACG=ref('ACG Evaluation of Abnormal Liver Chemistries Guideline','https://doi.org/10.1038/ajg.2016.517')
BSG=ref('BSG Guidelines on Management of Abnormal Liver Blood Tests','https://doi.org/10.1136/gutjnl-2017-314924')
AAS=ref('AASLD: Approach to Elevated Liver Enzymes','https://www.aasld.org/liver-fellow-network/core-series/back-basics/how-approach-elevated-liver-enzymes')
